from itertools import product

# Exact finite checker for the lower-degree identities in the stipulated q^r box.
# Inputs: i,j in {2,...,6}; (p,c) in {1,...,5}^2 with min(p,c)=1.

def partitions(n, top=None):
    if n == 0:
        yield ()
        return
    if top is None or top > n:
        top = n
    for a in range(top, 0, -1):
        for tail in partitions(n-a, a):
            yield (a,) + tail

def contains(mu, lam):
    return all((mu[k] if k < len(mu) else 0) >= a for k, a in enumerate(lam))

def in_box(mu, q, r):
    return len(mu) <= r and (not mu or mu[0] <= q)

def horizontal_strip(mu, lam):
    # Assumes mu contains lam.  The added cells must have distinct columns.
    columns = []
    for row in range(len(mu)):
        old = lam[row] if row < len(lam) else 0
        columns.extend(range(old + 1, mu[row] + 1))
    return len(columns) == len(set(columns))

def pieri(lam, k, q, r):
    return {mu for mu in partitions(sum(lam) + k)
            if in_box(mu, q, r) and contains(mu, lam)
            and horizontal_strip(mu, lam)}

def determinant(a):
    n = len(a)
    if n == 0:
        return 1
    if n == 1:
        return a[0][0]
    return sum(((-1) ** col) * a[0][col] * determinant(
        [row[:col] + row[col+1:] for row in a[1:]]) for col in range(n))

checks = 0
matrix_checks = 0
for i, j, p, c in product(range(2, 7), range(2, 7), range(1, 6), range(1, 6)):
    if min(p, c) != 1:
        continue
    q, r = i + p, j + c
    x0 = (i,) * j
    x1 = (i + 1,) + (i,) * (j - 1)
    y1 = (i,) * j + (1,)
    gamma = (i + 2,) + (i,) * (j - 1) if p >= 2 else None
    x2 = (i + 1, i + 1) + (i,) * (j - 2)
    z = (i + 1,) + (i,) * (j - 1) + (1,)
    y2 = (i,) * j + (2,)
    theta = (i,) * j + (1, 1) if c >= 2 else None

    expected_h1_x0 = {x1, y1}
    expected_h2_x0 = {z, y2} | ({gamma} if gamma is not None else set())
    expected_h1_x1 = {x2, z} | ({gamma} if gamma is not None else set())
    expected_h1_y1 = {z, y2} | ({theta} if theta is not None else set())
    assert pieri(x0, 1, q, r) == expected_h1_x0
    assert pieri(x0, 2, q, r) == expected_h2_x0
    assert pieri(x1, 1, q, r) == expected_h1_x1
    assert pieri(y1, 1, q, r) == expected_h1_y1
    checks += 4

    cols = [v for v in (gamma, x2, z, y2, theta) if v is not None]
    rows = [expected_h2_x0, expected_h1_x1, expected_h1_y1]
    matrix = [[int(col in row) for col in cols] for row in rows]
    if p == 1 and c == 1:
        assert cols == [x2, z, y2]
        assert matrix == [[0, 1, 1], [1, 1, 0], [0, 1, 1]]
        assert determinant([[matrix[a][b] for b in (1, 2)] for a in (0, 1)]) == -1
    elif p == 1:  # c >= 2
        assert cols == [x2, z, y2, theta]
        assert determinant([[matrix[a][b] for b in (1, 2, 3)] for a in (0, 1, 2)]) in (1, -1)
    else:          # p >= 2 and c == 1
        assert cols == [gamma, x2, z, y2]
        assert determinant([[matrix[a][b] for b in (0, 2, 3)] for a in (0, 1, 2)]) == 1
    matrix_checks += 1

print('INPUTS: i,j=2..6; p,c=1..5; min(p,c)=1')
print('PARAMETER_TUPLES:', matrix_checks)
print('PIERI_IDENTITIES_CHECKED:', checks)
print('BOUNDARY_MATRIX_CHECKS:', matrix_checks)
print('DOUBLY_BOUNDARY_MATRIX: [[0, 1, 1], [1, 1, 0], [0, 1, 1]]')
print('DOUBLY_BOUNDARY_MINOR_DETERMINANT: -1')
print('RESULT: PASS')
